import 'package:flutter/material.dart';
import '../../services/api_service.dart';
class SupervisorsScreen extends StatefulWidget{const SupervisorsScreen({super.key});@override State<SupervisorsScreen> createState()=>_SupervisorsScreenState();}
class _SupervisorsScreenState extends State<SupervisorsScreen>{List supervisors=[];bool loading=true;List<dynamic> list(dynamic x)=>x is List?List<dynamic>.from(x):x is Map&&x['data'] is List?List<dynamic>.from(x['data']):[];@override void initState(){super.initState();load();}void msg(Object e)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));Future<void> load()async{try{final r=await ApiService.get('supervisors');if(mounted)setState((){supervisors=list(r);loading=false;});}catch(e){if(mounted){setState(()=>loading=false);msg(e);}}}
Future<void> add()async{final n=TextEditingController(),p=TextEditingController(),e=TextEditingController();final k=GlobalKey<FormState>();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('إضافة مشرف'),content:Form(key:k,child:Column(mainAxisSize:MainAxisSize.min,children:[TextFormField(controller:n,decoration:const InputDecoration(labelText:'الاسم'),validator:(v)=>v!.trim().isEmpty?'مطلوب':null),TextFormField(controller:p,decoration:const InputDecoration(labelText:'الهاتف')),TextFormField(controller:e,decoration:const InputDecoration(labelText:'البريد'))]),),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),FilledButton(onPressed:(){if(k.currentState!.validate())Navigator.pop(c,true);},child:const Text('حفظ'))]));if(ok==true)try{await ApiService.post('supervisors',{'name':n.text.trim(),'phone':p.text.trim(),'email':e.text.trim(),'status':'active'});await load();}catch(x){msg(x);}finally{n.dispose();p.dispose();e.dispose();}}
Future<void> details(int id)async{try{final r=await ApiService.get('supervisors/$id');final d=Map<String,dynamic>.from(r['data']??r);if(!mounted)return;showDialog(context:context,builder:(c)=>AlertDialog(title:Text('${d['supervisor']?['name']??'المشرف'}'),content:SizedBox(width:460,child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Private: ${list(d['private_lessons']).length}'),Text('Group: ${list(d['group_lessons']).length}'),Text('إجمالي الحصص: ${d['lessons_count']??0}'),Text('مستحق الحصص: ${d['due']??0}'),Text('المدفوع: ${d['paid']??0}'),Text('المتبقي: ${d['remaining']??0}',style:const TextStyle(fontWeight:FontWeight.bold)),Text('المكافآت: ${d['bonus_total']??0}'),const Divider(),const Text('سجل الحصص',style:TextStyle(fontWeight:FontWeight.bold)),...list(d['lessons']).map((x)=>Text('• ${x['type']??''} / ${x['subject']??''} / ${x['starts_at']??''}'))])),),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('إغلاق'))]));}catch(e){msg(e);}}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('المشرفون'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton(onPressed:add,child:const Icon(Icons.add)),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView.builder(padding:const EdgeInsets.all(16),itemCount:supervisors.length,itemBuilder:(_,i){final s=supervisors[i];return Card(child:ListTile(onTap:()=>details(s['id']),leading:const CircleAvatar(child:Icon(Icons.supervisor_account)),title:Text('${s['name']??''}'),subtitle:Text('${s['phone']??''} • حصص: ${s['lessons_count']??0}'),trailing:const Icon(Icons.chevron_left)));}));}
